using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            SessionState.EraseString("LastSignal.RegressionPath");
            LastSignal.Editor.S001Project.RecoverMissingScene();
            LastSignal.Editor.CombatAcceptanceProject.RecoverMissingScene();
            EditorBuildSettings.scenes = new[]{new EditorBuildSettingsScene(LastSignal.Editor.S001Project.ScenePath, true), new EditorBuildSettingsScene("Assets/LastSignal/Scenes/CombatAcceptance.unity", true)};
            EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");
            result.Log("Both scene-only recoveries completed; build order retained.");
            UnityEditor.Compilation.CompilationPipeline.RequestScriptCompilation();
        }
    }
}
